package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.setFullScreen(true);
        primaryStage.setFullScreenExitHint("Press ESC to exit fullscreen");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package org.example.controller;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.example.model.Client;
import org.example.model.Commande;
import org.example.model.Depot;
import org.example.model.Produit;
import org.example.model.Stock;
import org.example.service.ClientService;
import org.example.service.ProduitService;
import org.example.service.CommandeService;
import org.example.service.StockService;

import java.io.IOException;
import java.time.LocalDate;
import java.util.logging.Logger;

public class DashboardController {

    private static final Logger logger = Logger.getLogger(DashboardController.class.getName());

    @FXML private BorderPane mainPane;
    @FXML private VBox sidebar;
    @FXML private Label totalClientsLabel;
    @FXML private Label totalProduitsLabel;
    @FXML private Label totalCommandesLabel;
    @FXML private Label alertesStockLabel;
    @FXML private Button nouveauClientBtn;
    @FXML private Button ajouterProduitBtn;
    @FXML private Button nouvelleCommandeBtn;
    @FXML private Button frontOfficeBtn;

    private final ClientService clientService = new ClientService();
    private final ProduitService produitService = new ProduitService();
    private final CommandeService commandeService = new CommandeService();
    private final StockService stockService = new StockService();

    @FXML
    public void initialize() {
        addSampleData();
        loadStats();
    }

    private void addSampleData() {
        // Sample products avec le nouveau constructeur
        // Produit(id, nom, description, prixUnitaire, quantiteStock, codeSku, categorie, seuilMinimum, actif)
        produitService.add(new Produit(0, "Paracétamol", "Antalgique et antipyrétique", 5.50, 100, "PARA001", "Analgésiques", 20, true));
        produitService.add(new Produit(0, "Ibuprofène", "Anti-inflammatoire non stéroïdien", 4.20, 80, "IBU002", "Anti-inflammatoires", 20, true));
        produitService.add(new Produit(0, "Aspirine", "Antalgique et antiagrégant", 3.80, 120, "ASP003", "Analgésiques", 20, true));
        produitService.add(new Produit(0, "Vitamine C", "Supplément vitaminique", 8.90, 50, "VIT004", "Vitamines", 20, true));

        // Sample clients
        clientService.add(new Client(0, "Dupont", "Jean", "jean.dupont@email.com", "0123456789", LocalDate.of(1980, 5, 15), "123 Rue de la Paix, Paris"));
        clientService.add(new Client(0, "Martin", "Marie", "marie.martin@email.com", "0987654321", LocalDate.of(1990, 3, 22), "456 Avenue des Champs, Lyon"));

        // Sample depots
        Depot depot1 = new Depot(0, "Dépôt Central", "10 Rue du Stock, Paris", "0145678901");
        Depot depot2 = new Depot(0, "Dépôt Régional", "20 Boulevard Commercial", "0276543210");

        // Sample stocks
        stockService.add(new Stock(0, produitService.getAll().get(0), 50, 10, depot1));
        stockService.add(new Stock(0, produitService.getAll().get(1), 5, 10, depot1)); // Low stock

        // Sample orders avec le nouveau constructeur
        // Commande(id, client, lignes, dateCommande, adresseLivraison, statut)
        commandeService.add(new Commande(0, clientService.getAll().get(0), java.util.Collections.emptyList(), LocalDate.now(), "", "brouillon"));
    }

    private void loadStats() {
        totalClientsLabel.setText(String.valueOf(clientService.getAll().size()));
        totalProduitsLabel.setText(String.valueOf(produitService.getAll().size()));
        totalCommandesLabel.setText(String.valueOf(commandeService.getAll().size()));
        alertesStockLabel.setText(String.valueOf(stockService.getStocksFaibles().size()));
    }

    @FXML
    private void handleNouveauClient() {
        // Open new client form
        logger.info("Nouveau Client clicked");
    }

    @FXML
    private void handleAjouterProduit() {
        // Open add product form
        logger.info("Ajouter Produit clicked");
    }

    @FXML
    private void handleNouvelleCommande() {
        // Open new order form
        logger.info("Nouvelle Commande clicked");
    }

    @FXML
    private void goToFrontOffice() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
        scene.getStylesheets().add(cssResource);
        Stage stage = (Stage) frontOfficeBtn.getScene().getWindow();
        stage.setScene(scene);
        stage.setFullScreen(true);
    }

    @FXML
    private void showClients() {
        // Switch to clients view
        logger.info("Show Clients");
    }

    @FXML
    private void showProduits() {
        // Ouvrir la vue Produits dans une nouvelle fenêtre
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Produits.fxml"));
            Parent root = loader.load();
            Scene scene = new Scene(root);
            String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
            scene.getStylesheets().add(cssResource);
            Stage stage = new Stage();
            stage.setTitle("Gestion des Produits");
            stage.setScene(scene);
            stage.setFullScreen(true);
            stage.show();
        } catch (IOException e) {
            logger.severe("Erreur lors du chargement de Produits.fxml: " + e.getMessage());
        }
    }

    @FXML
    private void showCommandes() {
        // Charger la vue Commandes.fxml dans le centre du dashboard
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Commandes.fxml"));
            Parent commandesView = loader.load();
            mainPane.setCenter(commandesView);
        } catch (IOException e) {
            logger.severe("Erreur lors du chargement de Commandes.fxml: " + e.getMessage());
        }
    }

    @FXML
    private void showPromotions() {
        // Switch to promotions view
        logger.info("Show Promotions");
    }

    @FXML
    private void showCoupons() {
        // Switch to coupons view
        logger.info("Show Coupons");
    }

    @FXML
    private void showDepots() {
        // Switch to depots view
        logger.info("Show Depots");
    }

    @FXML
    private void showStocks() {
        // Switch to stocks view
        logger.info("Show Stocks");
    }

    @FXML
    private void logout() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Login.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
        scene.getStylesheets().add(cssResource);
        Stage stage = (Stage) mainPane.getScene().getWindow();
        stage.setScene(scene);
        stage.setFullScreen(true);
    }
}

package org.example.controller;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.example.model.Client;
import org.example.model.Commande;
import org.example.model.Depot;
import org.example.model.Produit;
import org.example.model.Stock;
import org.example.service.ClientService;
import org.example.service.ProduitService;
import org.example.service.CommandeService;
import org.example.service.StockService;

import java.io.IOException;
import java.time.LocalDate;
import java.util.logging.Logger;

public class DashboardController {

    private static final Logger logger = Logger.getLogger(DashboardController.class.getName());

    @FXML private BorderPane mainPane;
    @FXML private VBox sidebar;
    @FXML private Label totalClientsLabel;
    @FXML private Label totalProduitsLabel;
    @FXML private Label totalCommandesLabel;
    @FXML private Label alertesStockLabel;
    @FXML private Button nouveauClientBtn;
    @FXML private Button ajouterProduitBtn;
    @FXML private Button nouvelleCommandeBtn;
    @FXML private Button frontOfficeBtn;

    private final ClientService clientService = new ClientService();
    private final ProduitService produitService = new ProduitService();
    private final CommandeService commandeService = new CommandeService();
    private final StockService stockService = new StockService();

    @FXML
    public void initialize() {
        addSampleData();
        loadStats();
    }

    private void addSampleData() {
        // Sample products avec le nouveau constructeur
        // Produit(id, nom, description, prixUnitaire, quantiteStock, codeSku, categorie, seuilMinimum, actif)
        produitService.add(new Produit(0, "Paracétamol", "Antalgique et antipyrétique", 5.50, 100, "PARA001", "Analgésiques", 20, true));
        produitService.add(new Produit(0, "Ibuprofène", "Anti-inflammatoire non stéroïdien", 4.20, 80, "IBU002", "Anti-inflammatoires", 20, true));
        produitService.add(new Produit(0, "Aspirine", "Antalgique et antiagrégant", 3.80, 120, "ASP003", "Analgésiques", 20, true));
        produitService.add(new Produit(0, "Vitamine C", "Supplément vitaminique", 8.90, 50, "VIT004", "Vitamines", 20, true));

        // Sample clients
        clientService.add(new Client(0, "Dupont", "Jean", "jean.dupont@email.com", "0123456789", LocalDate.of(1980, 5, 15), "123 Rue de la Paix, Paris"));
        clientService.add(new Client(0, "Martin", "Marie", "marie.martin@email.com", "0987654321", LocalDate.of(1990, 3, 22), "456 Avenue des Champs, Lyon"));

        // Sample depots
        Depot depot1 = new Depot(0, "Dépôt Central", "10 Rue du Stock, Paris", "0145678901");
        Depot depot2 = new Depot(0, "Dépôt Régional", "20 Boulevard Commercial", "0276543210");

        // Sample stocks
        stockService.add(new Stock(0, produitService.getAll().get(0), 50, 10, depot1));
        stockService.add(new Stock(0, produitService.getAll().get(1), 5, 10, depot1)); // Low stock

        // Sample orders avec le nouveau constructeur
        // Commande(id, client, lignes, dateCommande, adresseLivraison, statut)
        commandeService.add(new Commande(0, clientService.getAll().get(0), java.util.Collections.emptyList(), LocalDate.now(), "", "brouillon"));
    }

    private void loadStats() {
        totalClientsLabel.setText(String.valueOf(clientService.getAll().size()));
        totalProduitsLabel.setText(String.valueOf(produitService.getAll().size()));
        totalCommandesLabel.setText(String.valueOf(commandeService.getAll().size()));
        alertesStockLabel.setText(String.valueOf(stockService.getStocksFaibles().size()));
    }

    @FXML
    private void handleNouveauClient() {
        // Open new client form
        logger.info("Nouveau Client clicked");
    }

    @FXML
    private void handleAjouterProduit() {
        // Open add product form
        logger.info("Ajouter Produit clicked");
    }

    @FXML
    private void handleNouvelleCommande() {
        // Open new order form
        logger.info("Nouvelle Commande clicked");
    }

    @FXML
    private void goToFrontOffice() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
        scene.getStylesheets().add(cssResource);
        Stage stage = (Stage) frontOfficeBtn.getScene().getWindow();
        stage.setScene(scene);
        stage.setFullScreen(true);
    }

    @FXML
    private void showClients() {
        // Switch to clients view
        logger.info("Show Clients");
    }

    @FXML
    private void showProduits() {
        // Ouvrir la vue Produits dans une nouvelle fenêtre
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Produits.fxml"));
            loader.setControllerFactory(controller -> new ProduitsController());
            Parent root = loader.load();
            Scene scene = new Scene(root);
            String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
            scene.getStylesheets().add(cssResource);
            Stage stage = new Stage();
            stage.setTitle("Gestion des Produits");
            stage.setScene(scene);
            stage.setFullScreen(true);
            stage.show();
        } catch (IOException e) {
            logger.severe("Erreur lors du chargement de Produits.fxml: " + e.getMessage());
            e.printStackTrace();
        } catch (Exception e) {
            logger.severe("Erreur générale: " + e.getMessage());
            e.printStackTrace();
        }
    }

    @FXML
    private void showCommandes() {
        // Charger la vue Commandes.fxml dans le centre du dashboard
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Commandes.fxml"));
            Parent commandesView = loader.load();
            mainPane.setCenter(commandesView);
        } catch (IOException e) {
            logger.severe("Erreur lors du chargement de Commandes.fxml: " + e.getMessage());
        }
    }

    @FXML
    private void showPromotions() {
        // Switch to promotions view
        logger.info("Show Promotions");
    }

    @FXML
    private void showCoupons() {
        // Switch to coupons view
        logger.info("Show Coupons");
    }

    @FXML
    private void showDepots() {
        // Switch to depots view
        logger.info("Show Depots");
    }

    @FXML
    private void showStocks() {
        // Switch to stocks view
        logger.info("Show Stocks");
    }

    @FXML
    private void logout() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Login.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        String cssResource = getClass().getResource("/css/styles.css").toExternalForm();
        scene.getStylesheets().add(cssResource);
        Stage stage = (Stage) mainPane.getScene().getWindow();
        stage.setScene(scene);
        stage.setFullScreen(true);
    }
}

/* CuraVita Styles */

/* Root Variables */
.root {
    -primary-color: #145A44;
    -secondary-color: #1F7A5C;
    -accent-color: #2ECC71;
    -sidebar-bg: #0F3D2E;
    -background: #F5F7F6;
    -card-bg: #FFFFFF;
    -text-primary: #1E1E1E;
    -text-secondary: #6B7280;
    -text-on-dark: #FFFFFF;
}

/* General */
.root {
    -fx-background-color: -background;
    -fx-font-family: "Segoe UI", sans-serif;
}

/* Container for centered content */
.container {
    -fx-max-width: 1200px;
    -fx-alignment: center;
    -fx-padding: 40px;
}

/* Navbar Container - Centered wrapper */
.navbar-container {
    -fx-padding: 20px 40px;
    -fx-alignment: center;
    -fx-background-color: -background;
}

/* Navbar - Main bar */
.navbar {
    -fx-background-color: -card-bg;
    -fx-background-radius: 30px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 0 35px;
    -fx-pref-height: 70px;
    -fx-alignment: center;
    -fx-spacing: 0;
    -fx-pref-width: 90%;
}

.logo {
    -fx-text-fill: -primary-color;
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-min-width: 120px;
}

.nav-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 15px;
    -fx-border-color: transparent;
    -fx-cursor: hand;
    -fx-padding: 8px 14px;
    -fx-font-weight: 500;
    -fx-min-width: USE_PREF_SIZE;
}

.nav-item:hover {
    -fx-text-fill: -primary-color;
    -fx-background-color: rgba(20, 90, 68, 0.08);
    -fx-background-radius: 8px;
}

.search-field {
    -fx-pref-width: 220px;
    -fx-pref-height: 38px;
    -fx-background-radius: 20px;
    -fx-border-radius: 20px;
    -fx-padding: 8px 18px;
    -fx-font-size: 13px;
    -fx-border-color: #E5E7EB;
    -fx-border-width: 1px;
}

.nav-icon-button {
    -fx-background-color: -primary-color;
    -fx-text-fill: white;
    -fx-background-radius: 50%;
    -fx-min-width: 40px;
    -fx-min-height: 40px;
    -fx-pref-width: 40px;
    -fx-pref-height: 40px;
    -fx-cursor: hand;
    -fx-font-size: 16px;
    -fx-alignment: center;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

/* Profile Dropdown */
.profile-dropdown {
    -fx-background-color: -card-bg;
    -fx-background-radius: 10px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.15), 10, 0, 0, 4);
    -fx-padding: 8px 0;
    -fx-min-width: 150px;
    -fx-spacing: 0;
}

.dropdown-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 13px;
    -fx-padding: 12px 20px;
    -fx-alignment: center-left;
    -fx-cursor: hand;
    -fx-border-color: transparent;
}

.dropdown-item:hover {
    -fx-background-color: rgba(20, 90, 68, 0.1);
    -fx-text-fill: -primary-color;
}

/* Reusable Card */
.card {
    -fx-background-color: -card-bg;
    -fx-background-radius: 15px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 30px;
}

/* Card Hover Effect */
.card-hover:hover {
    -fx-scale-x: 1.02;
    -fx-scale-y: 1.02;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.15), 15, 0, 0, 8);
    -fx-transition: all 0.3s ease;
}

/* Primary Button */
.button-primary {
    -fx-background-color: -accent-color;
    -fx-text-fill: white;
    -fx-background-radius: 10px;
    -fx-padding: 12px 24px;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
}

.button-primary:hover {
    -fx-background-color: -secondary-color;
}

/* Hero Section */
.hero-section {
    -fx-background-color: -primary-color;
    -fx-padding: 80px 40px;
    -fx-alignment: center;
}

.hero-title {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 48px;
    -fx-font-weight: bold;
    -fx-margin-bottom: 20px;
}

.hero-subtitle {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 24px;
    -fx-opacity: 0.9;
}

/* Cards Section */
.cards-section {
    -fx-padding: 40px 0;
}

/* Card Title and Description */
.card-title {
    -fx-font-size: 24px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
    -fx-margin-bottom: 15px;
}

.card-description {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
    -fx-text-alignment: center;
    -fx-wrap-text: true;
}

/* Products Container */
.products-container {
    -fx-padding: 20px 0;
}

/* Sidebar */
.sidebar {
    -fx-background-color: -sidebar-bg;
    -fx-padding: 30px 20px;
    -fx-pref-width: 220px;
}

.sidebar-logo {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 24px;
    -fx-font-weight: bold;
    -fx-padding: 0 20px;
}

.sidebar-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 16px;
    -fx-alignment: center-left;
    -fx-padding: 15px 20px;
    -fx-background-radius: 8px;
    -fx-pref-width: 180px;
    -fx-cursor: hand;
    -fx-transition: all 0.3s ease;
}

.sidebar-item:hover {
    -fx-background-color: -secondary-color;
    -fx-translate-x: 5px;
}

.sidebar-button-bottom {
    -fx-background-color: -accent-color;
    -fx-text-fill: white;
    -fx-background-radius: 30px;
    -fx-padding: 12px 24px;
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
    -fx-pref-width: 180px;
    -fx-pref-height: 45px;
    -fx-margin: 0 20px 30px 20px;
    -fx-alignment: center;
}

.sidebar-button-bottom:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.02;
    -fx-scale-y: 1.02;
}

/* Main Content */
.main-scroll {
    -fx-background-color: transparent;
}

.main-content {
    -fx-padding: 40px;
    -fx-max-width: 1200px;
    -fx-alignment: center;
}

.main-title {
    -fx-font-size: 36px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
    -fx-margin-bottom: 20px;
}

/* Stats Cards */
.stat-card {
    -fx-background-color: -card-bg;
    -fx-padding: 25px;
    -fx-background-radius: 12px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 8, 0, 0, 4);
    -fx-alignment: center;
    -fx-pref-width: 180px;
    -fx-pref-height: 100px;
}

.stat-label {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
    -fx-margin-bottom: 10px;
}

.stat-value {
    -fx-text-fill: -text-primary;
    -fx-font-size: 42px;
    -fx-font-weight: bold;
}

/* Section Title */
.section-title {
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
}

/* Activity Item */
.activity-item {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
}

/* CuraVita Styles */

/* Root Variables */
.root {
    -primary-color: #145A44;
    -secondary-color: #1F7A5C;
    -accent-color: #2ECC71;
    -sidebar-bg: #0F3D2E;
    -background: #F5F7F6;
    -card-bg: #FFFFFF;
    -text-primary: #1E1E1E;
    -text-secondary: #6B7280;
    -text-on-dark: #FFFFFF;
}

/* General */
.root {
    -fx-background-color: -background;
    -fx-font-family: "Segoe UI", sans-serif;
}

/* Container for centered content */
.container {
    -fx-max-width: 1200px;
    -fx-alignment: center;
    -fx-padding: 40px;
}

/* Navbar Container - Centered wrapper */
.navbar-container {
    -fx-padding: 20px 40px;
    -fx-alignment: center;
    -fx-background-color: -background;
}

/* Navbar - Main bar */
.navbar {
    -fx-background-color: -card-bg;
    -fx-background-radius: 30px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 0 35px;
    -fx-pref-height: 70px;
    -fx-alignment: center;
    -fx-spacing: 0;
    -fx-pref-width: 90%;
}

.logo {
    -fx-text-fill: -primary-color;
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-min-width: 120px;
}

.nav-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 15px;
    -fx-border-color: transparent;
    -fx-cursor: hand;
    -fx-padding: 8px 14px;
    -fx-font-weight: 500;
}

.nav-item:hover {
    -fx-text-fill: -primary-color;
    -fx-background-color: rgba(20, 90, 68, 0.08);
    -fx-background-radius: 8px;
}

.search-field {
    -fx-pref-width: 220px;
    -fx-pref-height: 38px;
    -fx-background-radius: 20px;
    -fx-border-radius: 20px;
    -fx-padding: 8px 18px;
    -fx-font-size: 13px;
    -fx-border-color: #E5E7EB;
    -fx-border-width: 1px;
}

.nav-icon-button {
    -fx-background-color: -primary-color;
    -fx-text-fill: white;
    -fx-background-radius: 50%;
    -fx-min-width: 40px;
    -fx-min-height: 40px;
    -fx-pref-width: 40px;
    -fx-pref-height: 40px;
    -fx-cursor: hand;
    -fx-font-size: 16px;
    -fx-alignment: center;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

/* Profile Dropdown */
.profile-dropdown {
    -fx-background-color: -card-bg;
    -fx-background-radius: 10px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.15), 10, 0, 0, 4);
    -fx-padding: 8px 0;
    -fx-min-width: 150px;
    -fx-spacing: 0;
}

.dropdown-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 13px;
    -fx-padding: 12px 20px;
    -fx-alignment: center-left;
    -fx-cursor: hand;
    -fx-border-color: transparent;
}

.dropdown-item:hover {
    -fx-background-color: rgba(20, 90, 68, 0.1);
    -fx-text-fill: -primary-color;
}

/* Reusable Card */
.card {
    -fx-background-color: -card-bg;
    -fx-background-radius: 15px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 30px;
}

/* Card Hover Effect */
.card-hover:hover {
    -fx-scale-x: 1.02;
    -fx-scale-y: 1.02;
